// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.optimizer;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.List;
import java.util.Map;
import java.util.Set;

import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.EstimateVector;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cost.BagEstimate;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cost.EstimateMath;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cost.EvidenceProfile;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cost.FiniteRelationEstimate;
import org.junit.jupiter.api.Test;

/**
 * Exactness and uncertainty invariants of factor estimates: exactness is an explicit proof and is never inferred from a
 * confidence value, a reported q-error widens rather than removes the uncertainty interval, and a semi-join over an
 * unproven empty right side cannot produce a confident zero.
 */
class FactorEstimateExactnessInvariantTest {

	@Test
	void largerReportedQErrorMustNotShrinkUncertainty() {
		JoinFactorCostModel.FactorCostEstimate defaultQError = new JoinFactorCostModel.FactorCostEstimate(1_000.0d,
				1_000.0d);
		JoinFactorCostModel.FactorCostEstimate hundredfoldQError = new JoinFactorCostModel.FactorCostEstimate(
				1_000.0d, 1_000.0d, Map.of(), Map.of("plannedCardinalityQError", 100.0d));
		EstimateVector q4 = defaultQError.getNormalizedEstimateVector();
		EstimateVector q100 = hundredfoldQError.getNormalizedEstimateVector();
		assertTrue(q100.uncertaintyRows() >= q4.uncertaintyRows(),
				"q-error 100 reports uncertainty " + q100.uncertaintyRows() + " [" + q100.lowerRows() + ","
						+ q100.upperRows() + "] while default q-error 4 reports " + q4.uncertaintyRows() + " ["
						+ q4.lowerRows() + "," + q4.upperRows() + "]");
		assertTrue(q100.upperRows() > q100.lowerRows(),
				"a q-error of 100 must leave a non-degenerate interval: [" + q100.lowerRows() + "," + q100.upperRows()
						+ "]");
	}

	@Test
	void reportedQErrorMustWidenTheIntervalWithConfidenceGap() {
		JoinFactorCostModel.FactorCostEstimate lowConfidence = new JoinFactorCostModel.FactorCostEstimate(1_000.0d,
				1_000.0d, Map.of(), Map.of("plannedCardinalityQError", 10.0d, "plannedCardinalityConfidence", 0.1d));
		JoinFactorCostModel.FactorCostEstimate highConfidence = new JoinFactorCostModel.FactorCostEstimate(1_000.0d,
				1_000.0d, Map.of(), Map.of("plannedCardinalityQError", 10.0d, "plannedCardinalityConfidence", 0.9d));
		EstimateVector low = lowConfidence.getNormalizedEstimateVector();
		EstimateVector high = highConfidence.getNormalizedEstimateVector();
		assertTrue(low.uncertaintyRows() > high.uncertaintyRows(),
				"lower confidence must widen the interval: low=" + low.uncertaintyRows() + " high="
						+ high.uncertaintyRows());
		assertTrue(high.uncertaintyRows() > 0.0d, "a non-exact estimate must keep some uncertainty");
	}

	@Test
	void confidentBagEstimateMustNotBeReportedAsExact() {
		BagEstimate confidentSketch = new BagEstimate(1_000.0d, 1_000.0d, 0.0d, 1.0d, "sketch", Map.of(), Map.of(),
				Map.of());
		JoinFactorCostModel.FactorCostEstimate estimate = new JoinFactorCostModel.FactorCostEstimate(1_000.0d,
				1_000.0d).withBag(confidentSketch);
		assertFalse(estimate.hasExactOutputRows(),
				"a confidence of 1.0 is not an exactness proof; exactness must come from the explicit flag");
		EstimateVector vector = estimate.getNormalizedEstimateVector();
		assertTrue(vector.rowQErrorMax() > 1.0d,
				"an unproven estimate must keep a q-error above 1: " + vector.rowQErrorMax());
	}

	@Test
	void countedBagEstimateYieldsAnExactEstimate() {
		JoinFactorCostModel.FactorCostEstimate estimate = new JoinFactorCostModel.FactorCostEstimate(1_000.0d,
				1_000.0d).withBag(BagEstimate.exact(1_000.0d, "exact-count"));
		assertTrue(estimate.hasExactOutputRows(), "a counted bag carries an exactness proof");
		assertEquals(1.0d, estimate.getNormalizedEstimateVector().rowQErrorMax(), 0.0d);
	}

	@Test
	void exactnessDoesNotSurviveAHeuristicFilter() {
		EvidenceProfile counted = BagEstimate.exact(1_000.0d, "exact-count").evidenceProfile();
		EvidenceProfile filtered = counted.filter(0.5d, "heuristic-filter");
		assertEquals(1.0d, filtered.confidence(), 0.0d, "confidence is propagated unchanged by the filter");
		assertFalse(filtered.exact(), "a heuristic pass ratio removes the exactness proof");
		JoinFactorCostModel.FactorCostEstimate estimate = new JoinFactorCostModel.FactorCostEstimate(500.0d, 500.0d)
				.withBag(filtered.toBagEstimate());
		assertFalse(estimate.hasExactOutputRows(),
				"full confidence inherited through a heuristic filter is not an exactness proof");
		assertTrue(counted.filter(1.0d, "pass-through").exact(), "an identity filter keeps the proof");
		assertTrue(counted.project(Set.of("x")).exact() && counted.order().exact() && counted.slice(0L, 10L).exact(),
				"row-preserving operators keep the proof");
		assertFalse(counted.distinct(Set.of("x")).exact(), "DISTINCT over a variable is an estimate");
	}

	@Test
	void explicitExactFlagStillYieldsAnExactEstimate() {
		BagEstimate exactCount = new BagEstimate(1_000.0d, 1_000.0d, 0.0d, 1.0d, "exact", Map.of(), Map.of(),
				Map.of());
		JoinFactorCostModel.FactorCostEstimate estimate = new JoinFactorCostModel.FactorCostEstimate(1_000.0d,
				1_000.0d, Map.of(), Map.of(), false, false, 0, 0, Double.NaN, false, true).withBag(exactCount);
		assertTrue(estimate.hasExactOutputRows(), "the explicit exact flag must be honoured");
		EstimateVector vector = estimate.getNormalizedEstimateVector();
		assertEquals(1.0d, vector.rowQErrorMax(), 0.0d, "an exact estimate has q-error 1");
		assertEquals(1.0d, vector.confidence(), 0.0d, "an exact estimate has full confidence");
		assertEquals(0.0d, vector.uncertaintyRows(), 0.0d, "an exact estimate has no uncertainty");
	}

	@Test
	void lowConfidenceZeroMustNotBecomeAConfidentZeroThroughSemiJoin() {
		EvidenceProfile left = EvidenceProfile.of(1_000.0d, 1_000.0d, 0.0d, 0.9d, "left", Map.of(), Map.of(),
				Map.of(), Map.of());
		EvidenceProfile guessedEmptyRight = EvidenceProfile.of(0.0d, 0.0d, 0.0d, 0.05d, "sketch-miss", Map.of(),
				Map.of(), Map.of(), Map.of());
		EvidenceProfile exists = left.semiJoin(guessedEmptyRight, Set.of("x"));
		assertTrue(exists.rows() > 0.0d || exists.confidence() <= guessedEmptyRight.confidence(),
				"EXISTS over a 5%-confidence zero estimate yields rows=" + exists.rows() + " at confidence "
						+ exists.confidence());
	}

	@Test
	void lowConfidenceZeroLeftMustNotBecomeAConfidentZeroThroughSemiJoin() {
		EvidenceProfile guessedEmptyLeft = EvidenceProfile.of(0.0d, 0.0d, 0.0d, 0.05d, "sketch-miss", Map.of(),
				Map.of(), Map.of(), Map.of());
		EvidenceProfile right = EvidenceProfile.of(1_000.0d, 1_000.0d, 0.0d, 0.9d, "right", Map.of(), Map.of(),
				Map.of(), Map.of());
		EvidenceProfile exists = guessedEmptyLeft.semiJoin(right, Set.of("x"));
		assertTrue(exists.rows() > 0.0d || exists.confidence() <= guessedEmptyLeft.confidence(),
				"EXISTS over a 5%-confidence empty left side yields rows=" + exists.rows() + " at confidence "
						+ exists.confidence());
	}

	@Test
	void provenEmptyRightSideStillYieldsAnEmptySemiJoin() {
		EvidenceProfile left = EvidenceProfile.of(1_000.0d, 1_000.0d, 0.0d, 0.9d, "left", Map.of(), Map.of(),
				Map.of(), Map.of());
		EvidenceProfile provenEmptyRight = BagEstimate.exact(0.0d, "exact-count").evidenceProfile();
		EvidenceProfile exists = left.semiJoin(provenEmptyRight, Set.of("x"));
		assertEquals(0.0d, exists.rows(), 0.0d, "an exact empty right side proves an empty EXISTS");
		assertEquals(0.9d, exists.confidence(), 1.0e-12d, "an exact empty right side keeps the left confidence");
		assertTrue(exists.exact(), "an EXISTS over a counted empty right side is itself proven empty");
	}

	@Test
	void fullConfidenceEmptyRightSideWithoutProofDoesNotProveAnEmptySemiJoin() {
		EvidenceProfile left = EvidenceProfile.of(1_000.0d, 1_000.0d, 0.0d, 0.9d, "left", Map.of(), Map.of(),
				Map.of(), Map.of());
		EvidenceProfile confidentEmptyRight = EvidenceProfile.of(0.0d, 0.0d, 0.0d, 1.0d, "inherited-confidence",
				Map.of(), Map.of(), Map.of(), Map.of());
		EvidenceProfile exists = left.semiJoin(confidentEmptyRight, Set.of("x"));
		assertEquals(0.0d, exists.rows(), 0.0d);
		assertFalse(exists.exact(), "confidence 1.0 without a counted right side is not an emptiness proof");
	}

	@Test
	void fullConfidenceMinusCoverageWithoutProofDoesNotProveAnEmptyDifference() {
		List<String> variables = List.of("code");
		List<List<Value>> rows = List.of(List.of(literal("A")), List.of(literal("B")));
		FiniteRelationEstimate sampledRelation = FiniteRelationEstimate.fromRows(variables, rows, "sample");
		EvidenceProfile confidentLeft = new BagEstimate(2.0d, 2.0d, 0.0d, 1.0d, "sample", Map.of(), Map.of(),
				Map.of()).withFiniteRelation(sampledRelation).evidenceProfile();
		EvidenceProfile confidentRight = new BagEstimate(2.0d, 2.0d, 0.0d, 1.0d, "sample", Map.of(), Map.of(),
				Map.of()).withFiniteRelation(sampledRelation).evidenceProfile();
		EvidenceProfile difference = confidentLeft.difference(confidentRight, Set.of("code"));
		assertTrue(difference.rows() > 0.0d,
				"full coverage by an unproven right side is an estimate, not a proof that MINUS is empty: rows="
						+ difference.rows());

		EvidenceProfile countedLeft = BagEstimate.exact(2.0d, "count")
				.withFiniteRelation(sampledRelation)
				.evidenceProfile();
		EvidenceProfile countedRight = BagEstimate.exact(2.0d, "count")
				.withFiniteRelation(sampledRelation)
				.evidenceProfile();
		assertEquals(0.0d, countedLeft.difference(countedRight, Set.of("code")).rows(), 0.0d,
				"counted full coverage proves an empty MINUS");
	}

	@Test
	void innerJoinOverASampledBagCarryingADomainRelationIsNotExact() {
		// A FILTER IN-list domain attached to a sampled (heuristic) bag describes the possible values, not counted
		// rows; joining it with a counted VALUES bag must not turn the intersection size into an exactness proof.
		List<String> variables = List.of("o");
		FiniteRelationEstimate filterDomain = FiniteRelationEstimate.fromRows(variables,
				List.of(List.of(literal("A")), List.of(literal("C"))), "frontier-v2-query-filter-domain");
		FiniteRelationEstimate values = FiniteRelationEstimate.fromRows(variables,
				List.of(List.of(literal("A")), List.of(literal("B"))), "finite-values");
		BagEstimate sampled = BagEstimate.heuristic(5_000.0d, "frontier-v2-omni").withFiniteRelation(filterDomain);
		BagEstimate counted = BagEstimate.exact(2.0d, "finite-values").withFiniteRelation(values);

		BagEstimate joined = EstimateMath.innerJoin(sampled, counted, Set.of("o"));

		assertFalse(joined.isExact(), "a join with a sampled input is not counted: rows=" + joined.rows());
		assertFalse(new JoinFactorCostModel.FactorCostEstimate(joined.rows(), joined.rows()).withBag(joined)
				.hasExactOutputRows(), "the factor estimate must not claim exact output rows");

		BagEstimate countedLeft = BagEstimate.exact(2.0d, "count").withFiniteRelation(values);
		assertTrue(EstimateMath.innerJoin(countedLeft, counted, Set.of("o")).isExact(),
				"a join of two counted bags over their finite relations stays exact");
	}

	private static Value literal(String value) {
		return SimpleValueFactory.getInstance().createLiteral(value);
	}
}
